import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// 定义通用的好感度Schema
const FavorSchema = z.coerce.number()
  .transform(val => _.clamp(val, 0, 100))
  .prefault(0);

// 定义通用的位置Schema
const LocationSchema = z.string().prefault('罗德岛舰桥走廊');

// 定义通用的心情Schema
const MoodSchema = z.string().prefault('calm');

export const Schema = z.object({
  // 世界变量
  world: z.object({
    date: z.string().prefault('01月01日'),
    weekday: z.string().prefault('星期一'),
    time: z.string().prefault('09:00'),
    weather: z.string().prefault('晴朗'),
  }),

  // {{user}}（玩家）变量
  {{user}}: z.object({
    location: LocationSchema,
    virginity: z.boolean().prefault(true),
    // 修正：将 optional 改为 prefault 以确保数据稳定
    inventory: z.record(
      z.string().describe('Item Name'),
      z.object({
        description: z.string().prefault(''),
        count: z.coerce.number().prefault(1),
      })
    ).prefault({}),
  }),

  // 事件标记
  event: z.object({
    seen_nian_movie: z.boolean().prefault(false),
    entered_dusk_studio: z.boolean().prefault(false),
    drank_with_ling: z.boolean().prefault(false),
  }),

  // 四位龙娘的变量
  Nian: z.object({
    favor: FavorSchema,
    mood: MoodSchema.prefault('bored'),
    location: z.string().prefault('罗德岛食堂'),
  }),

  Ling: z.object({
    favor: FavorSchema,
    mood: MoodSchema.prefault('tipsy'),
    location: z.string().prefault('罗德岛观景台'),
  }),

  Shu: z.object({
    favor: FavorSchema,
    mood: MoodSchema.prefault('gentle'),
    location: z.string().prefault('罗德岛后厨'),
  }),

  Dusk: z.object({
    favor: FavorSchema,
    mood: MoodSchema.prefault('aloof'),
    location: z.string().prefault('画中门内的画室'),
  }),
});

$(() => {
  registerMvuSchema(Schema);
})

