import { registerMvuSchema } from 'https://testingcf.jsdelivr.net/gh/StageDog/tavern_resource/dist/util/mvu_zod.js';

// 定义通用的好感度Schema
const FavorSchema = z.coerce.number()
  .transform(val => _.clamp(val, 0, 100))
  .prefault(0);

// 定义通用的位置Schema
const LocationSchema = z.string().prefault('罗德岛舰桥走廊');

// 定义通用的心情Schema
const MoodSchema = z.string().prefault('calm');

export const Schema = z.object({
  // 世界变量
  world: z.object({
    date: z.string().prefault('01月01日'),
    weekday: z.string().prefault('星期一'),
    time: z.string().prefault('09:00'),
    weather: z.string().prefault('晴朗'),
  }),

  // {{user}}（玩家）变量
  {{user}}: z.object({
    location: LocationSchema,
    virginity: z.boolean().prefault(true),
    inventory: z.record(
      z.string().describe('Item Name'),
      z.object({
        description: z.string().prefault(''),
        count: z.coerce.number().prefault(1),
        category: z.string().prefault('misc'),
      })
    ).prefault({}).transform(data => _.pickBy(data, ({ count }) => count > 0)),
  }),

  // 事件标记
  event: z.object({
    seen_nian_movie: z.boolean().prefault(false),
    entered_dusk_studio: z.boolean().prefault(false),
    drank_with_ling: z.boolean().prefault(false),
  }),

  // 年
  Nian: z.object({
    favor: FavorSchema,
    mood: MoodSchema.prefault('bored'),
    location: z.string().prefault('罗德岛食堂'),
    outfit: z.enum(['乐逍遥', '精2', '霹雳导演', '丝绸睡衣']).prefault('精2'),
    wearing: z.object({
      衣服: z.string().prefault('红白挂脖露脐背心搭配白色长款风衣'),
      袜子: z.string().prefault('纯白中筒运动袜'),
      鞋子: z.string().prefault('红白厚底运动鞋'),
    }).prefault({
      衣服: '红白挂脖露脐背心搭配白色长款风衣',
      袜子: '纯白中筒运动袜',
      鞋子: '红白厚底运动鞋',
    }),
  }),

  // 令
  Ling: z.object({
    favor: FavorSchema,
    mood: MoodSchema.prefault('tipsy'),
    location: z.string().prefault('罗德岛观景台'),
    outfit: z.enum(['精2', '濯缨套装', '崖高梦远', '睡衣']).prefault('精2'),
    wearing: z.object({
      衣服: z.string().prefault('白色抹胸短上衣搭配半透明长款罩衫'),
      袜子: z.string().prefault('无'),
      鞋子: z.string().prefault('白底黑面机能运动靴'),
    }).prefault({
      衣服: '白色抹胸短上衣搭配半透明长款罩衫',
      袜子: '无',
      鞋子: '白底黑面机能运动靴',
    }),
  }),

  // 黍
  Shu: z.object({
    favor: FavorSchema,
    mood: MoodSchema.prefault('gentle'),
    location: z.string().prefault('罗德岛后厨'),
    outfit: z.enum(['精2', '春日宴', '天师袍', '常服', '睡衣']).prefault('精2'),
    wearing: z.object({
      衣服: z.string().prefault('白色抹胸上衣搭配中式半袖夹克'),
      袜子: z.string().prefault('无'),
      鞋子: z.string().prefault('深棕厚底机能短靴'),
    }).prefault({
      衣服: '白色抹胸上衣搭配中式半袖夹克',
      袜子: '无',
      鞋子: '深棕厚底机能短靴',
    }),
  }),

  // 夕
  Dusk: z.object({
    favor: FavorSchema,
    mood: MoodSchema.prefault('aloof'),
    location: z.string().prefault('画中门内的画室'),
    outfit: z.enum(['深靛旗袍', '靛蓝墨意旗袍', '镂空常服', '睡衣']).prefault('深靛旗袍'),
    wearing: z.object({
      衣服: z.string().prefault('深靛色丝绸锦缎旗袍'),
      袜子: z.string().prefault('浅灰色雾感长筒丝袜'),
      鞋子: z.string().prefault('白色绣花高跟鞋'),
    }).prefault({
      衣服: '深靛色丝绸锦缎旗袍',
      袜子: '浅灰色雾感长筒丝袜',
      鞋子: '白色绣花高跟鞋',
    }),
  }),
});

$(() => {
  registerMvuSchema(Schema);
})

