  .char-card.active-card { display: flex !important; }
  .inventory-panel.active-card { display: block !important; }

  @keyframes fadeIn {
      from { opacity: 0; transform: translateY(5px); }
      to { opacity: 1; transform: translateY(0); }
  }

  /* --- 呼吸光环动画 --- */
  @keyframes pulse-glow {
      0%, 100% {
          box-shadow:
              0 0 10px var(--theme-glow),
              0 0 20px rgba(var(--theme-color-rgb), 0.2),
              inset 0 0 10px rgba(var(--theme-color-rgb), 0.1);
      }
      50% {
          box-shadow:
              0 0 20px var(--theme-glow),
              0 0 40px rgba(var(--theme-color-rgb), 0.4),
