  .portrait-wrapper::after {
      content: '';
      position: absolute;
      top: -50%;
      left: -50%;
      width: 200%;
      height: 200%;
      background: conic-gradient(
          from 180deg,
          transparent 0deg,
          transparent 60deg,
          var(--theme-light) 90deg,
          var(--theme-color) 120deg,
          transparent 150deg,
          transparent 360deg
      );
      animation: rotate-gradient 4s linear infinite;
      z-index: 0;
      opacity: 0.7;
