      position: relative;
      width: 110px;
      height: 150px;
      background-color: rgba(0,0,0,0.9);
      border-radius: 6px;
      display: flex;
      justify-content: center;
      align-items: center;
      overflow: hidden;
      transition: all 0.4s ease;
      z-index: 1;
      animation: pulse-glow 3s ease-in-out infinite;
  }

  .placeholder-text {
      font-size: 12px;
      color: rgba(255,255,255,0.2);
      text-align: center;
      line-height: 1.5;
      z-index: 1;
