  .char-card .corner-decor-br {
      position: absolute;
      width: 40px;
      height: 40px;
      opacity: 0.3;
      pointer-events: none;
      transition: opacity 0.3s ease;
  }

  .corner-decor-tl { top: 5px; left: 5px; }
  .corner-decor-br { bottom: 25px; right: 5px; transform: rotate(180deg); }

  .char-card:hover .corner-decor-tl,
  .char-card:hover .corner-decor-br { opacity: 0.5; }

