  #card-nian .corner-decor-br {
      background:
          radial-gradient(ellipse at 50% 100%, #ff4400 0%, transparent 50%),
          radial-gradient(ellipse at 30% 80%, #ff6600 0%, transparent 40%),
          radial-gradient(ellipse at 70% 80%, #ff8800 0%, transparent 40%);
      filter: blur(2px);
  }

  #card-ling .corner-decor-tl,
  #card-ling .corner-decor-br {
      background: repeating-radial-gradient(
          circle at 50% 50%,
          transparent 0px,
          transparent 8px,
          rgba(0, 188, 212, 0.3) 8px,
          rgba(0, 188, 212, 0.3) 10px
      );
  }

  #card-dusk .corner-decor-tl,
  #card-dusk .corner-decor-br {
