    /* ========== 夕主题 - 竹叶完整飘落动画 ========== */
    @keyframes leaf-fall-full {
      0% {
        top: -30px;
        transform: rotate(0deg) translateX(0);
        opacity: 0;
      }
      5% {
        opacity: 0.7;
      }
      25% {
        transform: rotate(90deg) translateX(30px);
      }
      50% {
        transform: rotate(180deg) translateX(-20px);
      }
      75% {
        transform: rotate(270deg) translateX(25px);
      }
      100% {
        top: calc(100% + 20px);
        transform: rotate(360deg) translateX(0);
        opacity: 0;
      }
    }

    @keyframes ink-mist-drift {
      0%, 100% { transform: translateX(0) translateY(0) scale(1); opacity: 0.08; }
      50% { transform: translateX(15px) translateY(20px) scale(1.15); opacity: 0.2; }
    }

    /* ========== 黍主题动画 ========== */
    @keyframes rice-stalk-sway {
      0%, 100% { transform: rotate(-3deg); }
      50% { transform: rotate(3deg); }
    }

    @keyframes grain-gentle-bob {
      0%, 100% { transform: translateY(0); }
      50% { transform: translateY(2px); }
    }

    @keyframes harvest-glow {
      0%, 100% { filter: drop-shadow(0 0 4px rgba(218, 165, 32, 0.3)); }
      50% { filter: drop-shadow(0 0 10px rgba(218, 165, 32, 0.7)); }
    }

    /* ========== 黍主题 - 谷粒完整飘落动画 ========== */
    @keyframes grain-fall-full {
      0% {
        top: -20px;
        transform: rotate(0deg) scale(0.8) translateX(0);
        opacity: 0;
      }
      5% {
        opacity: 0.9;
        transform: rotate(20deg) scale(1) translateX(0);
      }
      25% {
        transform: rotate(90deg) scale(0.95) translateX(var(--grain-drift, 15px));
      }
      50% {
        transform: rotate(180deg) scale(0.9) translateX(calc(var(--grain-drift, 15px) * -0.5));
      }
      75% {
        transform: rotate(270deg) scale(0.85) translateX(calc(var(--grain-drift, 15px) * 0.7));
      }
      100% {
        top: calc(100% + 15px);
        transform: rotate(360deg) scale(0.5) translateX(0);
        opacity: 0;
      }
    }

    @keyframes golden-light-float-full {
      0%, 100% {
        transform: translateY(0) scale(1);
        opacity: 0.15;
      }
      50% {
        transform: translateY(40px) scale(1.25);
        opacity: 0.45;
      }
    }

    /* GIF淡入淡出 */
    @keyframes gif-fade-in {
      0% { opacity: 0; transform: scale(0.95); }
      100% { opacity: 1; transform: scale(1); }
    }

