      left: 50%;
      transform: translateX(-50%);
      width: 32px;
      height: 7px;
      background: linear-gradient(90deg, #8b7355, #a08050, #8b7355);
      border-radius: 50% 50% 0 0;
    }

    /* ========== 四角装饰 ========== */
    .corner-ornament {
      position: absolute;
      width: 40px;
      height: 40px;
      z-index: 10;
      pointer-events: none;
      animation: corner-glow-nian 4s ease-in-out infinite;
      transition: all 0.5s ease;
    }

    .corner-ornament::before,
    .corner-ornament::after {
      content: '';
      position: absolute;
      background: linear-gradient(135deg, #c4a35a, #8b7355);
    }

    .corner-tl { top: 5px; left: 5px; }
    .corner-tr { top: 5px; right: 5px; transform: rotate(90deg); }
    .corner-bl { bottom: 5px; left: 5px; transform: rotate(-90deg); }
    .corner-br { bottom: 5px; right: 5px; transform: rotate(180deg); }

    .corner-ornament::before {
      width: 30px;
      height: 4px;
      top: 0;
      left: 0;
      border-radius: 2px;
    }

    .corner-ornament::after {
      width: 4px;
      height: 30px;
      top: 0;
      left: 0;
      border-radius: 2px;
    }

    /* ========== 画框内层金边 ========== */
    .inner-frame {
      background: linear-gradient(to bottom, #c4a35a, #a08040, #c4a35a);
      padding: 4px;
      border-radius: 3px;
      box-shadow: inset 0 0 8px rgba(0, 0, 0, 0.3);
      transition: background 0.5s ease;
      position: relative;
      z-index: 3;
    }

    /* ========== 宣纸底纹 ========== */
    .xuan-paper {
      position: relative;
      background:
        repeating-linear-gradient(90deg, transparent, transparent 2px, rgba(139, 115, 85, 0.02) 2px, rgba(139, 115, 85, 0.02) 4px),
        repeating-linear-gradient(0deg, transparent, transparent 3px, rgba(139, 115, 85, 0.015) 3px, rgba(139, 115, 85, 0.015) 6px),
        linear-gradient(180deg, #faf6eb 0%, #f5f0e3 30%, #f8f4e8 70%, #f3eedf 100%);
      padding: 25px 30px 30px 30px;
      color: black;
      line-height: 1.85;
      border-radius: 2px;
      transition: background 0.5s ease;
      overflow: hidden;
    }

    .xuan-paper::before {
      content: '';
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
      opacity: 0.03;
      pointer-events: none;
      border-radius: 2px;
      z-index: 0;
    }

    /* ========== 正文内部特效层 ========== */
    .inner-effects {
      position: absolute;
      top: 0;
      left: 0;
      right: 0;
      bottom: 0;
      pointer-events: none;
      z-index: 1;
      opacity: 0;
      transition: opacity 0.5s ease;
      overflow: hidden;
    }

    /* === 年主题 - 真实火星完整飘落 === */
    .inner-nian .spark {
      position: absolute;
      left: var(--spark-x);
      animation: spark-fall-full 12s linear infinite, spark-twinkle 0.3s ease-in-out infinite;
