    .inner-nian .sp-7 { --spark-x: 85%; --spark-drift: 38px; animation-delay: 9s; }
    .inner-nian .sp-8 { --spark-x: 40%; --spark-drift: -35px; animation-delay: 10.5s; }

    .inner-nian .sp-1::before { width: 5px; height: 5px; }
    .inner-nian .sp-2::before { width: 7px; height: 7px; }
    .inner-nian .sp-3::before { width: 4px; height: 4px; }
    .inner-nian .sp-4::before { width: 6px; height: 6px; }
    .inner-nian .sp-5::before { width: 5px; height: 5px; }
    .inner-nian .sp-6::before { width: 8px; height: 8px; }
