    }

    .season-gif {
      position: absolute;
      top: 0;
      left: 0;
      width: 100%;
      height: 100%;
      object-fit: cover;
      opacity: 0;
      transition: opacity 0.5s ease;
      pointer-events: none;
    }

    .gif-nian { opacity: 1; }

    /* GIF切换 */
    #season-nian:checked ~ .chinese-frame .gif-nian { opacity: 1; animation: gif-fade-in 0.5s ease; }
