  <script type="module">
    const moodMap = {
        'bored': '无聊', 'excited': '兴奋', 'annoyed': '烦躁', 'happy': '开心', 'lazy': '慵懒',
        'tipsy': '微醺', 'serene': '淡然', 'nostalgic': '怀旧', 'melancholic': '惆怅', 'pleased': '欣慰',
        'gentle': '温和', 'caring': '关切', 'stern': '严肃', 'content': '满足', 'worried': '担忧',
        'aloof': '冷淡', 'focused': '专注', 'irritated': '恼怒', 'secretly_pleased': '暗喜', 'exhausted': '疲惫'
    };

    const statusDescMap = {
        nian: {
            'bored': '🎬 在片场打哈欠',
            'excited': '🎬 正在拍摄新场景',
            'annoyed': '🎬 对剧本不满意',
            'happy': '🎬 刚杀青一部烂片',
            'lazy': '🍜 窝在食堂吃火锅',
            'default': '🎬 在某处游荡'
        },
        ling: {
            'tipsy': '🍶 微醺中，诗兴大发',
            'serene': '🍶 独酌望月',
            'nostalgic': '🍶 回忆往昔战事',
            'melancholic': '🍶 对酒当歌',
            'pleased': '🍶 品了一坛好酒',
            'default': '🍶 不知在何处饮酒'
        },
        dusk: {
            'aloof': '🖌️ 画室门紧闭',
            'focused': '🖌️ 正在创作中',
            'irritated': '🖌️ 又毁了一幅画',
            'secretly_pleased': '🖌️ 对新作尚满意',
            'exhausted': '🖌️ 连续作画后休息',
            'default': '🖌️ 在画中世界里'
        },
        shu: {
            'gentle': '🌾 在后厨准备餐食',
            'caring': '🌾 正在照料某人',
            'stern': '🌾 在教训浪费粮食的人',
            'content': '🌾 看着丰收的作物',
            'worried': '🌾 担心妹妹们',
            'default': '🌾 在某处忙碌'
        }
    };

    const itemIcons = {
        '默认': '📦',
        '酒': '🍶',
        '画': '🖼️',
        '食物': '🍱',
        '钥匙': '🔑',
        '书': '📖',
        '信': '✉️'
    };

    function getItemIcon(itemName) {
        for (const [key, icon] of Object.entries(itemIcons)) {
            if (itemName.includes(key)) return icon;
        }
        return itemIcons['默认'];
    }

    function deepGet(obj, pathArray, defaultVal) {
        if (!obj || !pathArray || pathArray.length === 0) return defaultVal;
        let current = obj;
        for (const key of pathArray) {
            if (current === null || current === undefined) return defaultVal;
            if (typeof current !== 'object') return defaultVal;
            current = current[key];
        }
        return (current !== undefined && current !== null) ? current : defaultVal;
    }

    function getVar(allVars, path, defaultVal) {
        if (!allVars || typeof allVars !== 'object') return defaultVal;
        const pathParts = path.split('.');
        let value = deepGet(allVars, ['stat_data', ...pathParts], undefined);
        if (value !== undefined) return value;
        if (allVars.stat_data) {
            value = allVars.stat_data[path];
            if (value !== undefined) return value;
            value = deepGet(allVars.stat_data, pathParts, undefined);
            if (value !== undefined) return value;
        }
        value = deepGet(allVars, pathParts, undefined);
        if (value !== undefined) return value;
        if (typeof _ !== 'undefined' && typeof _.get === 'function') {
            value = _.get(allVars, `stat_data.${path}`);
            if (value !== undefined) return value;
            value = _.get(allVars, path);
            if (value !== undefined) return value;
        }
        return defaultVal;
    }

    function getInventory(allVars) {
        if (!allVars) return {};
        const possiblePaths = [
            ['stat_data', '阿蝶', 'inventory'],
            ['stat_data', 'adie', 'inventory'],
            ['阿蝶', 'inventory'],
            ['adie', 'inventory']
        ];
        for (const pathArray of possiblePaths) {
            const inventory = deepGet(allVars, pathArray, undefined);
            if (inventory && typeof inventory === 'object') {
                return inventory;
            }
        }
        if (allVars.stat_data && typeof allVars.stat_data === 'object') {
            for (const [key, value] of Object.entries(allVars.stat_data)) {
                if (value && typeof value === 'object' && value.inventory) {
                    return value.inventory;
                }
            }
        }
        return {};
    }

    function translateMood(moodKey) {
        return moodMap[moodKey] || moodKey || '平静';
    }

    function getStatusDesc(charId, mood) {
        const charDescs = statusDescMap[charId];
        if (!charDescs) return '状态未知';
        return charDescs[mood] || charDescs['default'] || '状态未知';
    }

    function updateInventory(vars) {
        const inventory = getInventory(vars);
        const $list = $('#inventory-list');
        const $count = $('#inventory-count');

        if (!inventory || typeof inventory !== 'object') {
            $count.text('0 件物品');
            $list.html(`
                <div class="inventory-empty">
                    <div class="inventory-empty-icon">🎒</div>
                    <div>背包空空如也</div>
                </div>
            `);
            return;
        }

        const items = Object.entries(inventory);
        $count.text(`${items.length} 件物品`);

        if (items.length === 0) {
            $list.html(`
                <div class="inventory-empty">
                    <div class="inventory-empty-icon">🎒</div>
                    <div>背包空空如也</div>
                </div>
            `);
            return;
        }

        const html = items.map(([name, data]) => {
            let desc = '无描述';
            let count = 1;
            if (typeof data === 'object' && data !== null) {
                desc = data.description || data.desc || '无描述';
                count = data.count || data.quantity || data.num || 1;
            } else if (typeof data === 'number') {
                count = data;
            } else if (typeof data === 'string') {
                desc = data;
            }
            const icon = getItemIcon(name);
            return `
                <div class="inventory-item">
                    <div class="item-icon">${icon}</div>
                    <div class="item-info">
                        <div class="item-name">${name}</div>
                        <div class="item-desc">${desc}</div>
                    </div>
                    <div class="item-count">×${count}</div>
                </div>
            `;
        }).join('');

        $list.html(html);
    }

    function updateStatus() {
        try {
            const vars = getAllVariables();
            if (!vars || typeof vars !== 'object') {
                return;
            }

            $('#sys-date').text(getVar(vars, 'world.date', '--月--日'));
            $('#sys-time').text(getVar(vars, 'world.time', '--:--'));
            $('#sys-weather').text(getVar(vars, 'world.weather', '未知'));
            $('#sys-location').text(getVar(vars, '阿蝶.location', '未知区域'));

            const chars = [
                { id: 'nian', key: 'Nian', event: 'event.seen_nian_movie' },
                { id: 'ling', key: 'Ling', event: 'event.drank_with_ling' },
                { id: 'dusk', key: 'Dusk', event: 'event.entered_dusk_studio' },
                { id: 'shu',  key: 'Shu',  event: null }
            ];

            chars.forEach(char => {
                const favor = getVar(vars, `${char.key}.favor`, 0);
                const mood = getVar(vars, `${char.key}.mood`, 'bored');
                const location = getVar(vars, `${char.key}.location`, '未知');

                $(`#val-${char.id}-location`).text(location);
                $(`#val-${char.id}-mood`).text(translateMood(mood));
                $(`#bar-${char.id}`).css('width', Math.min(Math.max(favor, 0), 100) + '%');
                $(`#num-${char.id}`).text(favor);

                const statusDesc = getStatusDesc(char.id, mood);
                $(`#desc-${char.id}`).html(statusDesc);

                if (char.event) {
                    const eventTriggered = getVar(vars, char.event, false);
                    if (eventTriggered) {
                        $(`#badge-${char.id}`).removeClass('hidden').addClass('active');
                    } else {
                        $(`#badge-${char.id}`).addClass('hidden');
                    }
                }
            });

            updateInventory(vars);

        } catch (e) {
            console.error('[Status] Update Error:', e);
        }
    }

    function switchTab(tabId) {
        $('.tab-btn').removeClass('active');
        $(`#tab-${tabId}`).addClass('active');
        $('.char-card, .inventory-panel').removeClass('active-card').addClass('hidden');
        $(`#card-${tabId}`).removeClass('hidden').addClass('active-card');

        const $wrapper = $('.status-wrapper');
        $wrapper.removeClass('theme-nian theme-ling theme-dusk theme-shu theme-inventory');
        $wrapper.addClass(`theme-${tabId}`);

        if (tabId === 'inventory') {
            updateStatus();
        }
    }

    async function init() {
        $(document).on('click', '.tab-btn', function(e) {
            e.preventDefault();
            const target = $(this).data('target');
            switchTab(target);
        });

        try {
            if (typeof waitGlobalInitialized === 'function') {
                await waitGlobalInitialized('Mvu');
            }
        } catch(e) {}

        updateStatus();

        if (!$('.tab-btn.active').length) {
            switchTab('nian');
        } else {
            const activeTab = $('.tab-btn.active').data('target');
            switchTab(activeTab);
        }

        if (window.eventOn && window.Mvu && Mvu.events) {
            eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, () => {
                updateStatus();
            });
            if (Mvu.events.VARIABLE_UPDATE_STARTED) {
                eventOn(Mvu.events.VARIABLE_UPDATE_STARTED, () => {
                    setTimeout(updateStatus, 100);
                });
            }
        }

